      row.appendChild(el('span', 'grow', entry.path));
      row.appendChild(el('span', 'dim', entry.byteSize + ' B'));
      row.appendChild(pill(entry.binary ? 'binary' : 'text', entry.binary ? undefined : 'plain'));
